17	COMMENT ON COLUMN rail_day_plan.schedule_key IS '计划业务键，全局唯一，取消后仍保留历史';
18	COMMENT ON COLUMN rail_day_plan.op_date IS '运营日期（Asia/Shanghai 日历日）';
19	COMMENT ON COLUMN rail_day_plan.version IS '计划版本，草稿占用整体替换成功一次加一';
20	COMMENT ON COLUMN rail_day_plan.status IS '计划状态：DRAFT 草稿 / PUBLISHED 已发布 / CANCELLED 已取消';
21	COMMENT ON COLUMN rail_day_plan.created_at IS '创建时刻，UTC 毫秒';
22	COMMENT ON COLUMN rail_day_plan.updated_at IS '最近变更时刻，UTC 毫秒';
23	
24	CREATE TABLE IF NOT EXISTS rail_plan_occupancy (
25	    id BIGINT NOT NULL AUTO_INCREMENT,
26	    plan_id BIGINT NOT NULL,
27	    seq INT NOT NULL,
28	    train_no VARCHAR(64) NOT NULL,
29	    section_id VARCHAR(64) NOT NULL,
30	    start_utc BIGINT NOT NULL,
31	    end_utc BIGINT NOT NULL,
32	    PRIMARY KEY (id)
33	);
34	COMMENT ON TABLE rail_plan_occupancy IS '计划区段占用明细，区间左闭右开；取消计划后历史占用保留不删除';
35	COMMENT ON COLUMN rail_plan_occupancy.id IS '主键';
36	COMMENT ON COLUMN rail_plan_occupancy.plan_id IS '所属计划 id，关联 rail_day_plan.id';
37	COMMENT ON COLUMN rail_plan_occupancy.seq IS '占用在计划内的序号，从 0 开始，保持提交顺序';
38	COMMENT ON COLUMN rail_plan_occupancy.train_no IS '列车编号';
39	COMMENT ON COLUMN rail_plan_occupancy.section_id IS '区段 ID';
40	COMMENT ON COLUMN rail_plan_occupancy.start_utc IS '占用开始时刻（含），UTC 毫秒';
41	COMMENT ON COLUMN rail_plan_occupancy.end_utc IS '占用结束时刻（不含），UTC 毫秒，必须大于 start_utc';
42	CREATE INDEX IF NOT EXISTS idx_rail_plan_occupancy_plan ON rail_plan_occupancy (plan_id);
43	CREATE INDEX IF NOT EXISTS idx_rail_plan_occupancy_section ON rail_plan_occupancy (section_id, start_utc, end_utc);
44	
45	CREATE TABLE IF NOT EXISTS idempotency_record (
46	    id BIGINT NOT NULL AUTO_INCREMENT,
47	    op_type VARCHAR(16) NOT NULL,
48	    request_key VARCHAR(128) NOT NULL,
49	    request_hash CHAR(64) NOT NULL,
50	    response_json CLOB NOT NULL,
51	    created_at BIGINT NOT NULL,
52	    PRIMARY KEY (id),
53	    CONSTRAINT uk_idempotency_op_key UNIQUE (op_type, request_key)
54	);
55	COMMENT ON TABLE idempotency_record IS '写操作幂等记录，仅缓存成功结果，失败不缓存可重试';
56	COMMENT ON COLUMN idempotency_record.id IS '主键';
57	COMMENT ON COLUMN idempotency_record.op_type IS '操作类型：CREATE / UPDATE / PUBLISH / CANCEL / RESCHEDULE';
58	COMMENT ON COLUMN idempotency_record.request_key IS '客户端幂等键，同一操作类型内唯一';
59	COMMENT ON COLUMN idempotency_record.request_hash IS '请求参数规范化后的 SHA-256，同键不同参判定 409';
60	COMMENT ON COLUMN idempotency_record.response_json IS '首次成功响应快照（JSON），重放原样返回';
61	COMMENT ON COLUMN idempotency_record.created_at IS '记录创建时刻，UTC 毫秒';
62	
63	CREATE TABLE IF NOT EXISTS rail_plan_reschedule_link (
64	    id BIGINT NOT NULL AUTO_INCREMENT,
65	    predecessor_plan_id BIGINT NOT NULL,
66	    successor_plan_id BIGINT NOT NULL,
67	    created_at BIGINT NOT NULL,
68	    PRIMARY KEY (id),
69	    CONSTRAINT uk_reschedule_link_predecessor UNIQUE (predecessor_plan_id),
70	    CONSTRAINT uk_reschedule_link_successor UNIQUE (successor_plan_id)
71	);
72	COMMENT ON TABLE rail_plan_reschedule_link IS '改签前后继关联，追加后不可变；一个计划最多一个直接前驱与一个直接后继';
73	COMMENT ON COLUMN rail_plan_reschedule_link.id IS '主键';
74	COMMENT ON COLUMN rail_plan_reschedule_link.predecessor_plan_id IS '直接前驱（被改签取消的旧计划）id，关联 rail_day_plan.id，全表唯一';
75	COMMENT ON COLUMN rail_plan_reschedule_link.successor_plan_id IS '直接后继（改签发布的新计划）id，关联 rail_day_plan.id，全表唯一';
76	COMMENT ON COLUMN rail_plan_reschedule_link.created_at IS '关联创建时刻，UTC 毫秒';
77	
78	CREATE TABLE IF NOT EXISTS publish_lock (
79	    id INT NOT NULL,
80	    PRIMARY KEY (id)
81	);
82	COMMENT ON TABLE publish_lock IS '发布/改签全局互斥锁，保证并发发布与改签按事务提交顺序裁决';
83	COMMENT ON COLUMN publish_lock.id IS '锁行 id，固定为 1，发布与改签时 SELECT ... FOR UPDATE 串行化';
84	
85	MERGE INTO publish_lock KEY(id) VALUES (1);
